"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["8407"],{1133(e,o,n){n.r(o),n.d(o,{metadata:()=>t,default:()=>u,frontMatter:()=>s,contentTitle:()=>r,toc:()=>d,assets:()=>l});var t=JSON.parse('{"id":"how-to/hardware/samples/legato-setup","title":"Getting Ready to Develop Legato Applications","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/samples/legato-setup.md","sourceDirName":"how-to/hardware/samples","slug":"/how-to/hardware/samples/legato-setup","permalink":"/personal-av-docs/docs/how-to/hardware/samples/legato-setup","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/samples/legato-setup.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Getting Ready to Develop Legato Applications","sidebar_label":"Getting Ready to Develop Legato Applicat","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/samples/legato-setup","format":"md"}}'),a=n(4848),i=n(8453);let s={title:"Getting Ready to Develop Legato Applications",sidebar_label:"Getting Ready to Develop Legato Applicat",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/samples/legato-setup",format:"md"},r,l={},d=[];function c(e){let o={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(o.p,{children:[":::note Edition\n",(0,a.jsx)(o.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(o.a,{href:"https://doc.airvantage.net/av/howto/hardware/samples/legato-setup",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsxs)(o.p,{children:["Getting Ready to Develop Legato Applications\nThis tutorials is deprecated.\nPlease have a look to\nthis page\n.\nObjective\nThis tutorial aims to provide setup information to users who want to rapidly get started developing Legato applications using Command-line mode.\nTutorial on developing Legato application using Developer Studio IDE will be made available in the near future.\nThe following steps are described, they are necessary to develop Legato applications:\nInterfacing with Legato device, in order to configure device and to control applications\nSetting up Legato application Development Environment on your host, in order to compile and install applications onto the target device\nRegistering your Legato device on AirVantage, so that the device can exchange data with the cloud server\nAlthough a mangOH board embedding a WP8548 module is used in this tutorial, guidelines provided in this page are also applicable to other Legato-based modules.\nPrerequisite\nThe mangOH board shall be correctly mounted (WP module, antennas, power, switches, etc) following this\nuser guide\nDownload appropriate\nfirmware packages\n(Customer Configuration package and Carrier Configuration package) then follow provided instruction to upgrade the device. Please note that signing up/in source.sierrawireless.com is required to download packages and drivers.\nSIM card with data call plan\nLinux PC running Ubuntu/Debian OS\nIf you\u2019d like to use your existing Host (e.g. MAC OSX, Windows) to develop Legato applications, you could use Virtual Machine, e.g. VirtualBox\nIf you are using Virtual Machine under Windows then install the\nUSB Drivers\nCreate an Ubuntu/Debian VM image. For instance, you can follow\nUbuntu on VirtualBox\nThen follow this tutorial\nHave an account on AirVantage server. If you don\u2019t,\nsign up here\nPart references used in this tutorial\nAirPrime WP8548 module\nmangOH board\nUbuntu 14.04.3 TLS\nPower adapter 12Vdc 1.5A\nUSB-to-Serial cable\nMicro-USB cable\n1 /\nHardware Setup\n2 /\nDev Host PC Setup\n3 /\nRegister\nAny issues ?\nIf you encounter any issue to set up your device, don\u2019t hesitate to use the\ndeveloper forum\nto benefit from the developer community experience.\nStep 1: Hardware Setup\nYour Host PC can interface with the Legato device to gain the following functionalities :\nAccess to device Linux Console to perform the following basic operations:\nRetrieve embedded system information\nGet Radio and Data connection status\nSet PIN code or remove PIN code\nRetrieve ethernet IP address\nInstall Legato Applications (developed on your host) onto the target device\nTo access device Linux console\n, the host can use ONE of the following interfaces:\nSerial port\nEthernet\nUSB\nTo install Legato applications\nonto Legato device, you can only use ONE of the following interfaces:\nEthernet\nUSB\nHow to gain access to device Linux console ?\nThere are 3 methods to access device Linux console.\nThe most straighforward is to use device Serial port.\nAccess to Legato Linux console over the Serial port\nLegato device\u2019s serial port is configured to be used for console input/output. To login, proceed the following:\nUse a Serial-to-USB cable to connect your device to your Host (PC/Mac)\nSetup a terminal emulator program (e.g. minicom, putty) on the host as follow:\nBaud rate : 115200 bps\nBits : 8\nParity: None\nStop Bits: 1\nOpen the serial connection, using the serial port being mapped to the USB port (e.g.\n/dev/ttyUSB0\nor\n/dev/ttyS0\n)\nOnce the serial port is opened, login as\nroot\n, there is no password by default. It is recommended to secure your platform by setting a password (\npasswd\n).\nTarget device USB driver is not required when using Serial-to-USB cable.\nYou can now enter Commands described in the below section\nLegato Device Setup and Configuration\nAccess to Legato Linux console over Ethernet\nThis option enables you to access the Linux console remotely using SSH. To login, proceed as follow:\nConnect your Legato device to your local network using an ethernet cable\nYour host (PC/Mac) should also be connected to the same network\nEstablish a SSH session from your host using the following command:\nssh root@<mangOH-ip-addr>\nPlease note that, the IP address of the device must be known prior using this ethernet option\nIt\u2019s easier to figure out the IP address of the device in a small local network. For instance, sudo nmap -sn 192.168.0.0/24\nYou could have your DHCP server to assign a fixed IP address to your device based on his MAC address\nUse a Serial connection (previous section) to access the Linux console, then use\nifconfig\ncommand to discover the IP or MAC adressses\nYou can now enter Commands described in the below section\nLegato Device Setup and Configuration\nAccess to mangOH Linux console over USB\nConnect your device\u2019s microUSB port to your PC using a USB cable\nUSB ECM mode is enabled by default on the target device:\nifconfig\ncommand shows a new network interface: usb0 along with assigned IP address for your host (default is 192.168.2.3)\nThe device exposes an ECM USB interface (Ethernet over USB) to the host under IP address 192.168.2.2 (default address)\nEstablish a SSH session from your host using the following command\nssh root@192.168.2.2\nYou can now enter Commands described in the below section\nLegato Device Setup and Configuration\nIf USB ECM mode is disabled on the target device:\nUse the Serial interface to access the device Linux console and then enable USB ECM mode. Refer to\nconfigEcm\ncommand in the next section\nLegato Device Setup and Configuration\nOnce you have connected the host to the device using one of the above interface (Serial, Ethernet or USB), as described in previous sections, you can now access device Linux console.\nAlthough any Linux commands can be used in the device Linux console, you may enter the following commands to discover or to change configuration.\nSystem Versions\ncm info\n, to display device model, IMEI, Serial Number, firmware and bootloader versions\nlegato version\n, to display Legato framework version\nRadio\ncm radio\nor\ncm radio status\n, to retrieve modem status\ncm radio on/off\n, to enable/disable radio\nrefer to\ncm radio\nfor more information on this command\nData Connectivity\ncm data\nor\ncm data info\n, to retrieve current profile in use\ncm data apn YourApn\n, to set APN for profile in use to YourApn\ncm data connect (optional timeout, secs)\n, to start a data connection for the optionally specified duration\nrefer to\ncm data\nfor more information on this command.\nApplications\napp status\n, to list applications status\napp start/stop/remove appName\n, to start or stop or remove application named\nappName\nrefer to\napp\nfor more information on this command\nSIM\ncm sim status\n, to retrieve SIM status\ncm sim info\n, to get SIM information\ncm sim enterpin\n, to enter SIM PIN code\ncm sim unlock pin\n, to disable SIM card security, won\u2019t request a PIN code when inserted or at the next system startup. Although, this is not recommanded for deployment, it is convenient for developers who need to reboot the board and to interact with it remotely using ssh\nrefer to\ncm sim\nfor more information on this command\nIP Address\nifconfig\n, Linux command, can be used to discover the IP address associated to the Ethernet (if connected). SSH over ethernet is an interesting option to connect to the device for development. Therefore, all above commands can be issued remotely with SSH. In your local network, you could assign a fixed IP address using the MAC address of eth0 interface.\nUSB mode\nconfigEcm show\n, to check whether the USB ECM mode is enable\nconfigEcm on\n, to activate the USB ECM mode. Device Reboot may be required. This mode enable your host to connect to your device using IP over USB.\nconfigEcm off\n, to deactivate the USB ECM mode. This is useful when you\u2019d need to upgrade the firmware locally using\nfdt\ntool\nIn Step 1, we\u2019ve covered how to:\nConnect your host to the Legato device using different options (Serial port, Ethernet or USB) in order to access device Linux Console\nIssue Commands in device Linux Concole in order to Retrieve information (e.g. IP address, software version) and Set basic configurations (e.g. SIM PIN, APN)\nStep 2: Legato Development Environment\nThis tutorial only covers development using Command-Line. Tutorial on using Developer Studio IDE will be available in the near future.\nBefore you can start developing Legato applications, the following conditions must be met:\nDevelopment Host should be running Ubuntu/Debian Linux and must have the following packages to be installed:\nLegato Framework\nLegato CLI (Linux Command Lines) tools\nTarget Device (Legato-based module)\nLegato version must be in sync with Legato Framwork version in the Host\nFirmware version must be compatible with Legato version\nUnderlying dependency such as bootloader, rootfs, os versions are covered by proper firmware package\nThe main setup flow to satisfy the aforementioned conditions can be summarized as follow:\nMake sure the Device firmware is compatible with the Legato framework version (e.g. 16.01), if not proceed to download appropriate\nfirmware package\nand follow provided instuction to upgrade the device.\nPrepare the host with the required packages/source/toolchain and Legato Framework.\nSetting Up the Ubuntu/Debian Development Host\nMinimum Configuration Requested: RAM: 1 GB / HDD: 5 GB free space / Ubuntu 15.04 recommended\nLegato is providing a complete set of Linux Command Lines (CLI) to develop your Legato applications. The legato-spm tool downloads everything needed to install the Legato CLI and embedded software packages for WP modules.\nDepending on your target distribution, follow one of these 2 steps to install legato-spm\nInstall legato-spm on Ubuntu/Debian distribution\nCheck your Ubuntu version\nlsb_release -d\nIf you are running an Ubuntu version older than 14.10 then install Java 8 as follow, otherwise proceed to\nInstall legato-spm\nsudo add-apt-repository ppa:openjdk-r/ppa\nsudo apt-get update\nsudo apt-get install openjdk-8-jre-headless\nsudo update-alternatives --config java\nInstall legato-spm\nwget ",(0,a.jsx)(o.a,{href:"http://updatesite.sierrawireless.com/legato-spm/debian/legato-spm.list",children:"http://updatesite.sierrawireless.com/legato-spm/debian/legato-spm.list"})," -O - | sudo tee /etc/apt/sources.list.d/legato-spm.list\nwget ",(0,a.jsx)(o.a,{href:"http://updatesite.sierrawireless.com/legato-spm/debian/legato-spm.key",children:"http://updatesite.sierrawireless.com/legato-spm/debian/legato-spm.key"})," -O - | sudo apt-key add -\nsudo apt-get update\nsudo apt-get install legato-spm\nInstall legato-spm on alternate distributions\nInstall requirements for legato-spm tool: openjdk-8-jre-headless\nInstall requirements to build Legato applications: build-essential python-jinja2 ninja-build\nDownload legato-spm tool archive from\nthis link\nExtract the archive to the location of your choice (e.g. unzip legato-spm*.zip -d $HOME/legato/spm)\nPotentially add this location to your user\u2019s path (e.g. echo \u2018export PATH=$HOME/legato/spm:$PATH\u2019 >> $HOME/.bashrc)\nDownload and install the latest Legato CLI tools and embedded software packages\nlegato-spm --install --module WP85XX --update-link\nFollowing packages are now installed in your ~/legato/packages directory:\nlegato.framework.*  - Prebuilt Legato framework packages\nlegato.toolchain.*  - GCC cross compiler Toolchains\nlegato.devimg.*     - Images to upgrade Legato devices system software\nlegato.recovery.*   - Tool to recover a bricked Legato device\nlegato.source.*     - Legato source distribution package\nUse this script to configure Legato, this script shall be launched once in each new terminal window you\u2019d use for Legato development\nsource ~/legato/packages/legato.sdk.latest/resources/configlegatoenv\nCompiling and Installing applications\nOnce the Legato CLI tools have been installed in your Ubuntu/Debian host, you are now ready to develop Legato applications.\nImportant\nIn this Step, your Host needs to be connected to your Legato device over IP (using USB or Ethernet). This IP connection is required to install Legato Applications onto the target.\nConnection over the Serial link cannot be used to install application\nLet\u2019s have a separated Terminal console dedicated to compiling and installing applications. Let\u2019s name it\nTerminal #1\nfor referencing convenience.\nIn Ubuntu, open a new Terminal console, #1\nLaunch the following script to setup environment variables for Legato Development\nsource ~/legato/packages/legato.sdk.latest/resources/configlegatoenv\nYou are now ready to compile sample applications in the apps/sample directory ($LEGATO_ROOT/apps/sample)\nGet into the\nhelloWorld\ndirectory and compile it for WP8548 (mangOH) target\ncd $LEGATO_ROOT/apps/sample/helloWorld\nmake wp85\nhelloWorld.wp85\nshould be generated as the result of the compilation\nInstall it onto mangOH target device\ninstapp helloWorld.wp85.update <mangOH-IPaddress>\nViewing Device logs\nIn the Ubuntu Host, let\u2019s have a separated Terminal console dedicated to mangOH log. Let\u2019s name it\nTerminal #2\nfor referencing convenience.\nIn Ubuntu, open a new Terminal console, #2\nSSH onto the device:\nssh root@mangOHIPaddress\nStart the logging:\nlogread -f\nThis terminal console will now display all logs\nManaging Applications on the Device\nIn the Ubuntu Host, let\u2019s have a separated Terminal console dedicated to device Linux Console. Let\u2019s name it\nTerminal #3\nfor referencing convenience.\nIn Ubuntu, open a new Terminal console, #3\nSSH onto the device:\nssh root@mangOHIPaddress\nVerify that\nhelloWorld\napplication has been installed:\napp status\nLaunch the app :\napp start helloWorld\nYou should be seeing \u201CHello, world\u201D log in Terminal #2. The helloWorld sample application just simply output this log using\nLE_INFO\nmacro.\nIn Step 2, we\u2019ve covered how to:\nSetup your Ubuntu/Debian host for Legato Development usage\nCompile applications, install application onto the Target device\nRemotely access to Target Device Linux console\nView Target device log\nStep 3: Register your Legato device on AirVantage\nBefore your Legato applications can exchange data with AirVantage, your Legato-based device must be registered on AirVantage. This step guide you through this registration procedure.\nDevice Registration on AirVantage\nAcces mangOH Linux console, using one of the methods described in the first step:\nCollect Device Identification information:\ncm info\nConnect to\nAirVantage web portal\nusing your personal account.\nGo to the\nRegister\nactivity\nProvide device information: Type, Serial Number, IMEI\nGive it a Name, for searching convenience\nProceed to\nRegister\nto finalize the registration\nYour device can now connect to AirVantage server.\nThe tutorial\nexchange asset data with AirVantage\nwill guide you through the connection and data exchange data with AirVantage."]})]})}function u(e={}){let{wrapper:o}={...(0,i.R)(),...e.components};return o?(0,a.jsx)(o,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},8453(e,o,n){n.d(o,{R:()=>s,x:()=>r});var t=n(6540);let a={},i=t.createContext(a);function s(e){let o=t.useContext(i);return t.useMemo(function(){return"function"==typeof e?e(o):{...o,...e}},[o,e])}function r(e){let o;return o=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),t.createElement(i.Provider,{value:o},e.children)}}}]);